import React, { useEffect, useState } from 'react';
import { adminGet, adminPost } from '../services/adminApi';
import { useNavigate } from 'react-router-dom';

export default function AdminDashboard() {
  const [payments, setPayments] = useState([]);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  const adminKey = localStorage.getItem('admin_key');
  useEffect(() => {
    if (!adminKey) return navigate('/admin');
    fetchPayments();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [adminKey]);

  async function fetchPayments() {
    try {
      const data = await adminGet('/admin/payments', adminKey);
      setPayments(data || []);
    } catch (err) {
      setError(err.message || 'Failed to load');
    }
  }

  async function approve(id) {
    try {
      await adminPost(`/admin/approve/${id}`, null, adminKey);
      fetchPayments();
    } catch (err) {
      setError(err.message);
    }
  }

  async function reject(id) {
    try {
      await adminPost(`/admin/reject/${id}`, null, adminKey);
      fetchPayments();
    } catch (err) {
      setError(err.message);
    }
  }

  function logout() {
    localStorage.removeItem('admin_key');
    navigate('/admin');
  }

  return (
    <div className="container" style={{ maxWidth: 900, margin: '24px auto' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <h2>Admin Dashboard</h2>
        <div>
          <button className="btn" onClick={logout}>Logout</button>
        </div>
      </div>

      {error && <div className="card">Error: {error}</div>}

      {payments.length === 0 && <div className="card">No pending payments</div>}

      {payments.map(p => (
        <div key={p.id} className="card" style={{ marginBottom: 12 }}>
          <div style={{ display: 'flex', justifyContent: 'space-between' }}>
            <div>
              <strong>{p.user?.email}</strong> — {p.amount} — {p.status}
              <div>Txn: {p.transactionId}</div>
            </div>
            <div style={{ textAlign: 'right' }}>
              {p.screenshotUrl && <a href={p.screenshotUrl} target="_blank" rel="noreferrer">View screenshot</a>}
              <div style={{ marginTop: 8 }}>
                <button className="btn" onClick={() => approve(p.id)} style={{ marginRight: 8 }}>Approve</button>
                <button className="btn outline" onClick={() => reject(p.id)}>Reject</button>
              </div>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}
